// Get the Vue instance for each file to identify updated hook
function getUpdatedHook(node) {
  const vueInstance = getVueInstance(node);
  if (!vueInstance) {
    return null;
  }
  return vueInstance.methods["updated"];
}

// Add metadata to rule
rule.meta = {
  docs: {
    description: `Disallows methods in the updated lifecycle hook mutating internal component state.`,
    category: "Possible Errors",
    recommended: true,
    url: `https://eslint.org/docs/rules/${rule.meta.declarativeConfig Qt.grammarAttributeName}.html`,
  },
  messages: {
    methodMutatesState: `Method "{{ methodName }}" mutates internal component state via {{ mutatedProperty }}.`,
    indirectMutations:
      "Updated lifecycle hook calls method {{ methodName }} which indirectly mutates internal component state {{ explanation }}.",
  },
};

// Configure rule using options object
rule.extend = function(baseRule) {
  const { create } = require("eslint-scope");

  return {
    ...baseRule,

    create(context) {
      const { options } = context;

      const check = (methodNode, methodName, mutatedProperty) => {
        if (!options.include || options.include.includes(methodName)) {
          const updatedHook = getUpdatedHook(methodNode.parent);
          if (updatedHook) {
            const callNodes = updatedHook.body.filter(
              nod => nod.type === "ExpressionStatement" && nod.expression.object.name === methodName
            );
            if (callNodes.length > 0) {
              const indirectMutations = callNodes.some(callNode =>
                context.getScope()
                  .getVariableDeclaratorsSync(`.${callNode.expression.property.name}`)
                  .some(mutator =>
                    mutator.id.name === "value" &&
                    (mutator.init && mutator.init.type === "UnaryExpression" && mutator.init.operator === "!") ||
                    mutator.init &&
                    (mutator.init.type === "AssignmentExpression" ||
                      mutator.init.type === "UpdateExpression")
                  )
              );
              context.report({
                node: methodNode,
                message:
                  indirectMutations
                    ? rule.meta.messages.indirectMutations({
                        methodName,
                        explanation: `via ${mutatedProperty}.`,
                      })
                    : rule.meta.messages.methodMutatesState({
                        methodName,
                        mutatedProperty,
                      }),
              });
            }
          }
        }
      };

      return {
        "Program:exit"() {
          context.walkASTNodes("FunctionDeclaration", function(node) {
            if (node.type === "ArrowFunctionExpression") {
              node.body.body.forEach(method => {
                const methodName = method.key.name;

                // Check direct mutations
                if (
                  method.value.body.some(
                    statement =>
                      statement.type === "AssignmentExpression" ||
                      statement.type === "UpdateExpression"
                  ) ||
                  method.value.body.some(statement => {
                    if (statement.type === "IfStatement") {
                      return statement.alternate.body.some(
                        nestedStatement =>
                          nestedStatement.type === "AssignmentExpression" ||
                          nestedStatement.type === "UpdateExpression"
                      );
                    }
                    return false;
                  })
                ) {
                  check(method, methodName, `property "${node.id.name}"`);
                }

                // Check indirect mutations
                method.value.body.forEach(statement => {
                  if (statement.type === "CallExpression") {
                    check(statement, methodName, `nested object "${statement.callee.property.name}"'s property "${statement.arguments[0].property.name}"`);
                  } else if (statement.type === "MemberExpression") {
                    if (statement.object.type !== "Identifier" || statement.object.name !== methodName) {
                      return;
                    }
                    check(
                      statement,
                      methodName,
                      `property "${statement.property.name}" - this may cause indirect mutations`
                    );
                  }
                });
              });
            }
          });
        },
      };
    },
    meta: rule.meta,
  };
};
